begin;
alter table public.applyall_institutions add column if not exists eff_member_status text not null default 'NOT_PARTICIPATING' check (eff_member_status in ('NOT_PARTICIPATING','PROSPECT','VERIFICATION','AGREEMENT_PENDING','ACTIVE','PAUSED','ENDED')), add column if not exists eff_member_since timestamptz, add column if not exists eff_receiver_enabled boolean not null default false;
create table public.applyall_common_applications (id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.applyall_profiles(id) on delete cascade,cycle text not null default '2027',applicant_type text not null default 'FIRST_YEAR',status text not null default 'DRAFT' check(status in('DRAFT','READY_TO_REVIEW','SUBMITTED','WITHDRAWN')),legal_name text,preferred_name text,date_of_birth date,phone text,address jsonb not null default '{}'::jsonb,citizenship text,high_school jsonb not null default '{}'::jsonb,academics jsonb not null default '{}'::jsonb,activities jsonb not null default '[]'::jsonb,honors jsonb not null default '[]'::jsonb,family jsonb not null default '{}'::jsonb,essay text,additional_information text,certification_version text,certified_at timestamptz,submitted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(profile_id,cycle,applicant_type));
create table public.applyall_college_users (id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.applyall_institutions(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'READER' check(role in('ADMISSIONS_ADMIN','READER')),active boolean not null default true,verified_at timestamptz,created_at timestamptz not null default now(),unique(institution_id,user_id));
create table public.applyall_common_submissions (id uuid primary key default gen_random_uuid(),common_application_id uuid not null references public.applyall_common_applications(id) on delete restrict,institution_id uuid not null references public.applyall_institutions(id) on delete restrict,profile_id uuid not null references public.applyall_profiles(id) on delete restrict,snapshot jsonb not null,snapshot_hash text not null,certification_version text not null,authorized_at timestamptz not null,delivered_at timestamptz not null default now(),first_viewed_at timestamptz,first_downloaded_at timestamptz,status text not null default 'DELIVERED' check(status in('DELIVERED','VIEWED','DOWNLOADED','WITHDRAWN')),created_at timestamptz not null default now(),unique(common_application_id,institution_id));
create table public.applyall_college_interest (id uuid primary key default gen_random_uuid(),institution_name text not null,institution_email text not null,contact_name text not null,title text,phone text,message text,status text not null default 'NEW',created_at timestamptz not null default now());
alter table public.applyall_common_applications enable row level security; alter table public.applyall_college_users enable row level security; alter table public.applyall_common_submissions enable row level security; alter table public.applyall_college_interest enable row level security;
create policy "students own common application" on public.applyall_common_applications for all using(exists(select 1 from public.applyall_profiles p where p.id=profile_id and p.user_id=auth.uid())) with check(exists(select 1 from public.applyall_profiles p where p.id=profile_id and p.user_id=auth.uid()));
create policy "students read own common submissions" on public.applyall_common_submissions for select using(exists(select 1 from public.applyall_profiles p where p.id=profile_id and p.user_id=auth.uid()));
create policy "college users read membership" on public.applyall_college_users for select using(user_id=auth.uid());
create policy "college users read delivered applications" on public.applyall_common_submissions for select using(exists(select 1 from public.applyall_college_users cu where cu.institution_id=applyall_common_submissions.institution_id and cu.user_id=auth.uid() and cu.active and cu.verified_at is not null));
create policy "public may request college participation" on public.applyall_college_interest for insert with check(true);
create or replace function public.submit_eff_common_application(p_application_id uuid,p_institution_ids uuid[],p_certification_version text) returns table(submission_id uuid,institution_id uuid,status text) language plpgsql security invoker set search_path=public as $$ declare v_app public.applyall_common_applications;v_payload jsonb;v_hash text;v_institution uuid;v_submission uuid; begin select a.* into v_app from public.applyall_common_applications a join public.applyall_profiles p on p.id=a.profile_id where a.id=p_application_id and p.user_id=auth.uid() for update;if v_app.id is null then raise exception 'Application not found';end if;if v_app.legal_name is null or v_app.date_of_birth is null or v_app.essay is null then raise exception 'Complete all required application fields';end if;if coalesce(array_length(p_institution_ids,1),0)=0 then raise exception 'Select at least one participating college';end if;v_payload=to_jsonb(v_app)-'created_at'-'updated_at';v_hash=encode(digest(convert_to(v_payload::text,'UTF8'),'sha256'),'hex');foreach v_institution in array p_institution_ids loop if not exists(select 1 from public.applyall_institutions i where i.id=v_institution and i.active and i.eff_member_status='ACTIVE' and i.eff_receiver_enabled) then raise exception 'One or more schools are not verified EFF participating institutions';end if;insert into public.applyall_common_submissions(common_application_id,institution_id,profile_id,snapshot,snapshot_hash,certification_version,authorized_at) values(v_app.id,v_institution,v_app.profile_id,v_payload,v_hash,p_certification_version,now()) on conflict(common_application_id,institution_id) do nothing returning id into v_submission;if v_submission is null then select s.id into v_submission from public.applyall_common_submissions s where s.common_application_id=v_app.id and s.institution_id=v_institution;end if;submission_id:=v_submission;institution_id:=v_institution;status:='DELIVERED';return next;end loop;update public.applyall_common_applications set status='SUBMITTED',certification_version=p_certification_version,certified_at=now(),submitted_at=now(),updated_at=now() where id=v_app.id;end $$;
commit;
